package com.fitbite.controller; import com.fitbite.dto.*; import com.fitbite.dto.AdminDtos.*; import com.fitbite.repository.*; import org.springframework.web.bind.annotation.*; import java.util.Map; import org.springframework.security.access.prepost.PreAuthorize;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController{private final UserRepository users;private final RecipeRepository recipes;private final CategoryRepository cats;private final HealthGoalRepository goals;public AdminController(UserRepository u,RecipeRepository r,CategoryRepository c,HealthGoalRepository g){users=u;recipes=r;cats=c;goals=g;}@GetMapping("/stats") public ApiResponse<Stats> stats(){long fav=users.findAll().stream().mapToLong(u->u.getFavorites().size()).sum();return ApiResponse.ok("Admin statistics",new Stats(users.count(),recipes.count(),cats.count(),goals.count(),fav));}@GetMapping("/users") public ApiResponse<?> userList(){return ApiResponse.ok("Users fetched",users.findAll().stream().map(u->java.util.Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"role",u.getRoles().stream().findFirst().map(r->r.getName().name()).orElse("USER"))).toList());}}
